import { sha1 } from '@noble/hashes/legacy.js';

/**
 * Google Play purchase signature check, on the phone, no server and no native code.
 * Play signs each purchase's JSON with the app's licence key: RSASSA-PKCS1-v1_5 over SHA-1 ("SHA1withRSA").
 * The public key is the base64 X.509 SubjectPublicKeyInfo shown in Play Console (Monetisation setup, Licensing).
 * Pure and tested against keys generated by Node's crypto.
 */

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
export function b64ToBytes(s: string): Uint8Array {
  const clean = s.replace(/[\s=]/g, '').replace(/-/g, '+').replace(/_/g, '/');
  const out: number[] = [];
  let buf = 0, bits = 0;
  for (const ch of clean) {
    const v = B64.indexOf(ch);
    if (v < 0) throw new Error('bad base64');
    buf = (buf << 6) | v; bits += 6;
    if (bits >= 8) { bits -= 8; out.push((buf >> bits) & 0xff); }
  }
  return Uint8Array.from(out);
}

const toBig = (b: Uint8Array) => { let n = BigInt(0); for (const x of b) n = (n << BigInt(8)) | BigInt(x); return n; };

function modPow(base: bigint, exp: bigint, mod: bigint): bigint {
  let r = BigInt(1), b = base % mod, e = exp;
  const ZERO = BigInt(0), ONE = BigInt(1);
  while (e > ZERO) { if (e & ONE) r = (r * b) % mod; b = (b * b) % mod; e >>= ONE; }
  return r;
}

/** Minimal DER reader: enough for SubjectPublicKeyInfo { AlgorithmIdentifier, BIT STRING { RSAPublicKey { n, e } } }. */
function readTLV(d: Uint8Array, at: number): { tag: number; start: number; end: number } {
  const tag = d[at];
  let len = d[at + 1], p = at + 2;
  if (len & 0x80) { const n = len & 0x7f; len = 0; for (let i = 0; i < n; i++) len = (len << 8) | d[p + i]; p += n; }
  if (p + len > d.length) throw new Error('bad DER');
  return { tag, start: p, end: p + len };
}

export interface RsaKey { n: bigint; e: bigint; bytes: number }
export function parsePublicKey(b64: string): RsaKey {
  const d = b64ToBytes(b64);
  const spki = readTLV(d, 0); if (spki.tag !== 0x30) throw new Error('not SPKI');
  const alg = readTLV(d, spki.start); if (alg.tag !== 0x30) throw new Error('no algorithm');
  const bit = readTLV(d, alg.end); if (bit.tag !== 0x03) throw new Error('no key');
  const rsa = readTLV(d, bit.start + 1); if (rsa.tag !== 0x30) throw new Error('not RSA');
  const nT = readTLV(d, rsa.start), eT = readTLV(d, nT.end);
  if (nT.tag !== 0x02 || eT.tag !== 0x02) throw new Error('bad RSA key');
  let nb = d.subarray(nT.start, nT.end); while (nb.length && nb[0] === 0) nb = nb.subarray(1);
  return { n: toBig(nb), e: toBig(d.subarray(eT.start, eT.end)), bytes: nb.length };
}

// DigestInfo prefix for SHA-1 (RFC 8017, section 9.2)
const SHA1_PREFIX = [0x30, 0x21, 0x30, 0x09, 0x06, 0x05, 0x2b, 0x0e, 0x03, 0x02, 0x1a, 0x05, 0x00, 0x04, 0x14];

/** True only when `signatureB64` is a valid SHA1withRSA signature of `data` (UTF-8) under `key`. Never throws. */
export function verifySha1Rsa(data: string, signatureB64: string, key: RsaKey | null): boolean {
  try {
    if (!key || !data || !signatureB64) return false;
    const sig = b64ToBytes(signatureB64);
    if (sig.length !== key.bytes) return false;
    const s = toBig(sig);
    if (s >= key.n) return false;
    let m = modPow(s, key.e, key.n);
    const em = new Uint8Array(key.bytes);
    for (let i = key.bytes - 1; i >= 0; i--) { em[i] = Number(m & BigInt(0xff)); m >>= BigInt(8); }
    const hash = sha1(new TextEncoder().encode(data));
    const tail = [...SHA1_PREFIX, ...hash];
    const padEnd = key.bytes - tail.length - 1;
    if (padEnd < 10) return false;
    let diff = em[0] ^ 0x00;
    diff |= em[1] ^ 0x01;
    for (let i = 2; i < padEnd; i++) diff |= em[i] ^ 0xff;
    diff |= em[padEnd] ^ 0x00;
    for (let i = 0; i < tail.length; i++) diff |= em[padEnd + 1 + i] ^ tail[i];
    return diff === 0;
  } catch {
    return false;
  }
}
